from __future__ import annotations

import datetime as _dt
import hashlib
from typing import Iterable


def now_local() -> _dt.datetime:
    return _dt.datetime.now().astimezone().replace(tzinfo=None)


def format_timestamp(dt: _dt.datetime) -> str:
    return dt.strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3]


def format_date(dt: _dt.date) -> str:
    return dt.strftime("%Y-%m-%d")


def format_summary_datetime(dt: _dt.datetime) -> str:
    return dt.strftime("%Y-%m-%d %H:%M:%S")


def today_local() -> _dt.date:
    return now_local().date()


def sha256_hex(parts: Iterable[bytes]) -> str:
    h = hashlib.sha256()
    for part in parts:
        h.update(part)
    return h.hexdigest()


def stable_hash_basic(question: str, answer: str) -> str:
    # Hash is derived from normalized card content only. The exact input format
    # is behaviorally inferred and kept isolated here for future adjustment.
    return sha256_hex(
        [
            b"basic",
            len(question.encode("utf-8")).to_bytes(8, "little"),
            question.encode("utf-8"),
            len(answer.encode("utf-8")).to_bytes(8, "little"),
            answer.encode("utf-8"),
        ]
    )


def stable_hash_cloze_family(text: str) -> str:
    return sha256_hex(
        [
            b"cloze-family",
            len(text.encode("utf-8")).to_bytes(8, "little"),
            text.encode("utf-8"),
        ]
    )


def stable_hash_cloze(text: str, start: int, end: int) -> str:
    return sha256_hex(
        [
            b"cloze",
            len(text.encode("utf-8")).to_bytes(8, "little"),
            text.encode("utf-8"),
            start.to_bytes(8, "little", signed=False),
            end.to_bytes(8, "little", signed=False),
        ]
    )

