@dataclass
class FinishedSession:
    started_at: dt.datetime
    ended_at: dt.datetime
    total_cards: int
    reviews: list[Review]


class DrillApp:
    def __init__(
        self,
        collection: Collection,
        conn: sqlite3.Connection,
        performance: dict[str, Performance],
        cards: list[Card],
        answer_controls: str,
        port: int,
    ) -> None:
        self.collection = collection
        self.conn = conn
        self.performance = performance
        self.answer_controls = answer_controls
        self.port = port
        self.lock = threading.RLock()
        self.cards_total = len(cards)
        self.pending = list(cards)
        self.current = self.pending.pop(0)
        self.revealed = False
        self.history: list[tuple[Card, Review]] = []
        self.started_at = now_local()
        self.finished: FinishedSession | None = None
        self.shutdown_requested = False

    def handle_action(self, action: str) -> None:
        with self.lock:
            if action == "Shutdown":
                self.shutdown_requested = True
                return
            if action == "End":
                if self.finished is None:
                    self._finish(now_local())
                else:
                    self._persist_duplicate_end(now_local())
                return
            if self.finished is not None:
                return
            if action == "Reveal":
                self.revealed = True
                return
            if action == "Undo":
                if not self.history:
                    return
                if self.current is not None:
                    self.pending.insert(0, self.current)
                card, _review = self.history.pop()
                self.current = card
                self.revealed = False
                return
            if action in {"Forgot", "Hard", "Good", "Easy"}:
                reviewed_at = now_local()
                previous = self.performance.get(self.current.hash)
                review = schedule_review(self.current.hash, action, reviewed_at, previous)
                self.history.append((self.current, review))
                self.current = self.pending.pop(0) if self.pending else None
                self.revealed = False
                if self.current is None:
                    self._finish(reviewed_at)

    def _finish(self, ended_at: dt.datetime) -> None:
        reviews = [review for _, review in self.history]
        db.insert_session(
            self.conn,
            format_timestamp(self.started_at),
            format_timestamp(ended_at),
            reviews,
        )
        self.finished = FinishedSession(
            started_at=self.started_at,
            ended_at=ended_at,
            total_cards=self.cards_total,
            reviews=reviews,
        )

    def _persist_duplicate_end(self, ended_at: dt.datetime) -> None:
        if self.finished is None:
            return
        db.insert_session(
            self.conn,
            format_timestamp(self.finished.started_at),
            format_timestamp(ended_at),
            self.finished.reviews,
        )
        self.finished = FinishedSession(
            started_at=self.finished.started_at,
            ended_at=ended_at,
            total_cards=self.finished.total_cards,
            reviews=list(self.finished.reviews),
        )

    def progress_percent(self) -> int:
        reviewed = len(self.history)
        if self.cards_total == 0:
            return 100
        return int(round((reviewed / self.cards_total) * 100))

    def render_page(self) -> str:
        with self.lock:
            if self.finished is not None:
                return _render_finished_page(self.finished)
            return _render_active_page(
                app=self,
                card=self.current,
                collection=self.collection,
                port=self.port,
                answer_controls=self.answer_controls,
            )

    def should_shutdown(self) -> bool:
        with self.lock:
            return self.shutdown_requested


def select_session_cards(
    cards: list[Card],
    performance: dict[str, Performance],
    *,
    card_limit: int | None,
    new_card_limit: int | None,
    from_deck: str | None,
    bury_siblings: bool,
    today: dt.date,
) -> list[Card]:
    due_cards: list[Card] = []
    new_cards: list[Card] = []
    for card in cards:
        if from_deck and card.deck_name != from_deck:
            continue
        perf = performance.get(card.hash)
        if perf is None:
            new_cards.append(card)
            continue
        due = dt.date.fromisoformat(perf.due_date)
        if due <= today:
            due_cards.append(card)
    random.shuffle(due_cards)
    random.shuffle(new_cards)
    if bury_siblings:
        due_cards = _bury_siblings(due_cards)
        new_cards = _bury_siblings(new_cards)
    if new_card_limit is not None:
        new_cards = new_cards[: new_card_limit]
    selected = list(due_cards)
    if card_limit is None or len(selected) < card_limit:
        remaining = None if card_limit is None else max(card_limit - len(selected), 0)
        if remaining is None:
            selected.extend(new_cards)
        else:
            selected.extend(new_cards[:remaining])
    else:
        selected = selected[:card_limit]
    random.shuffle(selected)
    return selected


def _bury_siblings(cards: list[Card]) -> list[Card]:
    seen: set[str] = set()
    out: list[Card] = []
    for card in cards:
        key = card.family_hash or card.hash
        if key in seen:
            continue
        seen.add(key)
        out.append(card)
    return out


def run_server(
    collection: Collection,
    conn: sqlite3.Connection,
    performance: dict[str, Performance],
    cards: list[Card],
    host: str,
    port: int,
    answer_controls: str,
    open_browser: bool,
) -> int:
    app = DrillApp(collection, conn, performance, cards, answer_controls, port)
    server = _make_server(host, port, app)
    if open_browser:
        try:
            import webbrowser

            webbrowser.open(f"http://{host}:{port}/")
        except Exception:
            pass
    try:
        server.serve_forever()
    finally:
        server.server_close()
    return 0


def _make_server(host: str, port: int, app: DrillApp) -> ThreadingHTTPServer:
    class Handler(BaseHTTPRequestHandler):
        def do_GET(self) -> None:
            parsed = urllib.parse.urlparse(self.path)
            if parsed.path == "/":
                self._send_bytes(
                    HTTPStatus.OK,
                    app.render_page().encode("utf-8"),
                    "text/html; charset=utf-8",
                )
                return
            if parsed.path == "/style.css":
                self._send_bytes(HTTPStatus.OK, STYLE_CSS.encode("utf-8"), "text/css")
                return
            if parsed.path == "/script.js":
                macros_lines = ["let MACROS = {};"]
                for key, value in app.collection.macros:
                    macros_lines.append(
                        "MACROS["
                        + repr(key)
                        + "] = "
                        + repr(value)
                        + ";"
                    )
                body = "\n".join(macros_lines) + "\n" + BASE_SCRIPT
                self._send_bytes(
                    HTTPStatus.OK,
                    body.encode("utf-8"),
                    "text/javascript",
                )
                return
            if parsed.path == "/katex/katex.css":
                self._send_bytes(
                    HTTPStatus.OK,
                    KATEX_CSS.encode("utf-8"),
                    "text/css",
                )
                return
            if parsed.path == "/katex/katex.js":
                self._send_bytes(
                    HTTPStatus.OK,
                    KATEX_JS.encode("utf-8"),
                    "text/javascript",
                )
                return
            if parsed.path == "/katex/mhchem.js":
                self._send_bytes(
                    HTTPStatus.OK,
                    MHCHEM_JS.encode("utf-8"),
                    "text/javascript",
                )
                return
            if parsed.path.startswith("/file/"):
                rel_path = urllib.parse.unquote(parsed.path[len("/file/") :])
                full_path = os.path.abspath(os.path.join(app.collection.directory, rel_path))
                root = os.path.abspath(app.collection.directory)
                if not full_path.startswith(root + os.sep) and full_path != root:
                    self._send_not_found()
                    return
                if not os.path.isfile(full_path):
                    self._send_not_found()
                    return
                with open(full_path, "rb") as handle:
                    data = handle.read()
                content_type = mimetypes.guess_type(full_path)[0] or "application/octet-stream"
                self._send_bytes(HTTPStatus.OK, data, content_type)
                return
            self._send_not_found()

        def do_POST(self) -> None:
            parsed = urllib.parse.urlparse(self.path)
            if parsed.path != "/":
                self._send_not_found()
                return
            length = int(self.headers.get("Content-Length", "0"))
            raw = self.rfile.read(length).decode("utf-8")
            form = urllib.parse.parse_qs(raw)
            action = form.get("action", [""])[0]
            app.handle_action(action)
            self.send_response(HTTPStatus.SEE_OTHER)
            self.send_header("location", "/")
            self.send_header("content-length", "0")
            self.end_headers()
            if app.should_shutdown():
                threading.Thread(target=self.server.shutdown, daemon=True).start()

        def log_message(self, fmt: str, *args: object) -> None:
            return

        def _send_bytes(self, status: HTTPStatus, data: bytes, content_type: str) -> None:
            self.send_response(status)
            self.send_header("content-type", content_type)
            self.send_header("content-length", str(len(data)))
            if self.path.startswith("/katex/") or self.path == "/style.css":
                self.send_header("cache-control", "public, max-age=604800, immutable")
            self.end_headers()
            self.wfile.write(data)

        def _send_not_found(self) -> None:
            self._send_bytes(
                HTTPStatus.NOT_FOUND,
                b"Not Found",
                "text/html; charset=utf-8",
            )

    return ThreadingHTTPServer((host, port), Handler)


def _render_active_page(
    app: DrillApp,
    card: Card,
    collection: Collection,
    port: int,
    answer_controls: str,
) -> str:
    progress = app.progress_percent()
    if card.kind == "basic":
        question_html = render_card_question(card, collection, port, app.revealed)
        answer_html = render_card_answer(card, collection, port) if app.revealed else ""
        content_html = (
            f"<div class=\"question rich-text\">{question_html}</div>"
            f"<div class=\"answer rich-text\">{answer_html}</div>"
        )
    else:
        prompt_html = render_card_question(card, collection, port, app.revealed)
        content_html = f"<div class=\"prompt rich-text\">{prompt_html}</div>"
    if app.revealed:
        grades = _render_grades(answer_controls)
    else:
        grades = '<input id="reveal" type="submit" name="action" value="Reveal" title="Show the answer. Shortcut: space.">'
    undo = (
        '<input id="undo" type="submit" name="action" value="Undo" title="Undo last action. Shortcut: u.">'
        if app.history
        else '<input id="undo" type="submit" name="action" value="Undo" disabled>'
    )
    return (
        "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\">"
        "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">"
        "<title>hashcards</title>"
        "<link rel=\"stylesheet\" href=\"/katex/katex.css\">"
        "<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css\">"
        "<script defer src=\"/katex/katex.js\"></script>"
        "<script defer src=\"/katex/mhchem.js\"></script>"
        "<script defer src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js\"></script>"
        "<link rel=\"stylesheet\" href=\"/style.css\">"
        "<style>.card-content { opacity: 0; }</style>"
        "<noscript><style>.card-content { opacity: 1; }</style></noscript>"
        "</head><body>"
        "<div class=\"root\">"
        "<div class=\"header\"><div class=\"progress-bar\"><div class=\"progress-fill\" style=\"width: "
        + str(progress)
        + "%;\"></div></div></div>"
        "<div class=\"card-container\"><div class=\"card\">"
        f"<div class=\"card-header\"><h1>{html.escape(card.deck_name)}</h1></div>"
        f"<div class=\"card-content\">{content_html}</div>"
        "</div></div>"
        "<div class=\"controls\"><form action=\"/\" method=\"post\">"
        + undo
        + "<div class=\"spacer\"></div>"
        + grades
        + "<div class=\"spacer\"></div>"
        + '<input id="end" type="submit" name="action" value="End" title="End the session (changes are saved)">'
        + "</form></div></div>"
        "<script src=\"/script.js\"></script></body></html>"
    )


def _render_grades(answer_controls: str) -> str:
    if answer_controls == "binary":
        return (
            "<div class=\"grades\">"
            '<input id="forgot" type="submit" name="action" value="Forgot" title="Mark card as forgotten.">'
            '<input id="good" type="submit" name="action" value="Good" title="Mark card as remembered.">'
            "</div>"
        )
    return (
        "<div class=\"grades\">"
        '<input id="forgot" type="submit" name="action" value="Forgot" title="Mark card as forgotten. Shortcut: 1.">'
        '<input id="hard" type="submit" name="action" value="Hard" title="Mark card as difficult. Shortcut: 2.">'
        '<input id="good" type="submit" name="action" value="Good" title="Mark card as remembered well. Shortcut: 3.">'
        '<input id="easy" type="submit" name="action" value="Easy" title="Mark card as very easy. Shortcut: 4.">'
        "</div>"
    )


def _render_finished_page(session: FinishedSession) -> str:
    duration_seconds = int((session.ended_at - session.started_at).total_seconds())
    reviewed = len(session.reviews)
    pace = 0.0 if reviewed == 0 else duration_seconds / reviewed
    return (
        "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\">"
        "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">"
        "<title>hashcards</title>"
        "<link rel=\"stylesheet\" href=\"/katex/katex.css\">"
        "<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css\">"
        "<script defer src=\"/katex/katex.js\"></script>"
        "<script defer src=\"/katex/mhchem.js\"></script>"
        "<script defer src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js\"></script>"
        "<link rel=\"stylesheet\" href=\"/style.css\">"
        "<style>.card-content { opacity: 0; }</style>"
        "<noscript><style>.card-content { opacity: 1; }</style></noscript>"
        "</head><body><div class=\"finished\">"
        "<h1>Session Completed 🎉</h1>"
        f"<div class=\"summary\">Reviewed {reviewed} cards in {duration_seconds} seconds.</div>"
        "<h2>Session Stats</h2>"
        "<div class=\"stats\"><table><tbody>"
        f"<tr><td class=\"key\">Total Cards</td><td class=\"val\">{session.total_cards}</td></tr>"
        f"<tr><td class=\"key\">Cards Reviewed</td><td class=\"val\">{reviewed}</td></tr>"
        f"<tr><td class=\"key\">Started</td><td class=\"val\">{format_summary_datetime(session.started_at)}</td></tr>"
        f"<tr><td class=\"key\">Finished</td><td class=\"val\">{format_summary_datetime(session.ended_at)}</td></tr>"
        f"<tr><td class=\"key\">Duration (seconds)</td><td class=\"val\">{duration_seconds}</td></tr>"
        f"<tr><td class=\"key\">Pace (s/card)</td><td class=\"val\">{pace:.2f}</td></tr>"
        "</tbody></table></div>"
        "<div class=\"shutdown-container\"><form action=\"/\" method=\"post\">"
        '<input class="shutdown-button" id="shutdown" type="submit" name="action" value="Shutdown" title="Shut down the server">'
        "</form></div></div><script src=\"/script.js\"></script></body></html>"
    )

