from __future__ import annotations

import datetime as dt

from .types import Performance, Review
from .util import format_date, format_timestamp


# Observed first-review values from the reference binary.
FIRST_REVIEW = {
    "Forgot": {"stability": 0.40255, "difficulty": 7.1949},
    "Hard": {"stability": 1.18385, "difficulty": 6.488305268471453},
    "Good": {"stability": 3.173, "difficulty": 5.282434422319005},
    "Easy": {"stability": 15.69105, "difficulty": 3.2245015893713678},
}


def schedule_review(
    card_hash: str,
    grade: str,
    reviewed_at: dt.datetime,
    previous: Performance | None,
) -> Review:
    if previous is None:
        stability = FIRST_REVIEW[grade]["stability"]
        difficulty = FIRST_REVIEW[grade]["difficulty"]
    else:
        stability, difficulty = _next_review(previous, grade)
    interval_raw = stability
    interval_days = max(1, int(round(interval_raw)))
    due_date = reviewed_at.date() + dt.timedelta(days=interval_days)
    return Review(
        review_id=None,
        session_id=None,
        hash=card_hash,
        reviewed_at=format_timestamp(reviewed_at),
        grade=grade,
        stability=stability,
        difficulty=difficulty,
        interval_raw=interval_raw,
        interval_days=interval_days,
        due_date=format_date(due_date),
    )


def _next_review(previous: Performance, grade: str) -> tuple[float, float]:
    # A lightweight approximation for later reviews. The benchmark-visible
    # observations pin down the first review exactly; later transitions are
    # inferred pragmatically rather than copied from any upstream source.
    stability = float(previous.stability)
    difficulty = float(previous.difficulty)
    if grade == "Forgot":
        return max(0.4, stability * 0.45), min(10.0, difficulty + 0.8)
    if grade == "Hard":
        return max(1.0, stability * 1.2), min(10.0, difficulty + 0.25)
    if grade == "Good":
        return max(1.0, stability * 2.2), max(1.0, difficulty - 0.15)
    return max(1.0, stability * 4.2), max(1.0, difficulty - 0.5)

